<?php use app\services\Ui;use app\services\Catalog;use app\models\User;use yii\helpers\Html;$this->title='Foydalanuvchilar';$super=Yii::$app->user->identity->role==='superadmin';$orgLabels=\app\services\Organization::labels($orgs);$orgOptions=[];foreach($orgs as $o)$orgOptions[$o['id']]=['data-kind'=>$o['kind'],'data-parent'=>$o['parent_id']??''];$this->registerJsFile(Yii::$app->request->baseUrl.'/js/admin-organization.js?v=1');$profile=json_decode($edit?->hemis_profile??'{}',true)?:[];$v=fn($key,$default='')=>Yii::$app->request->post($key,$edit?$edit->$key:$default); ?>
<div class="page-heading"><div><span class="eyebrow">ADMINISTRATOR</span><h1>Foydalanuvchilar</h1><p>Hisoblar, toifalar va vakolatlarni boshqaring.</p></div></div><?php if($super || $edit): ?><div class="form-grid"><section class="card"><h2><?= $edit?'Hisobni tahrirlash':'Yangi foydalanuvchi' ?></h2><?= Html::beginForm(['admin/users','id'=>$edit?->id],'post') ?><div class="two-columns"><?= Ui::input('F.I.Sh.','name',$v('name'),'text',['required'=>true,'maxlength'=>200]) ?><?= Ui::input('Login','username',$v('username'),'text',['required'=>true,'maxlength'=>80]) ?><?php if($super): ?><?= Ui::select('Rol','role',$v('role','unassigned'),User::ROLES) ?><?php else: ?><p class="muted">Rol: <?= Ui::h(User::ROLES[$edit?->role??'unassigned']) ?>. Rollarni faqat superadministrator o‘zgartiradi.</p><?php endif ?><?= Ui::select('KPI toifasi','category',$v('category'),[''=>'Yo‘q']+Catalog::CATEGORIES) ?><div data-org-assignment><div data-org-cascade hidden><?php foreach(['university'=>'Universitet','faculty'=>'Fakultet','department'=>'Kafedra'] as $level=>$label): ?><?= Ui::select($label,'org_picker_'.$level,'',[''=>'Yo‘q'],['data-org-level'=>$level]) ?><?php endforeach ?></div><?= Ui::select('Biriktirilgan to‘liq tuzilma','org_id',$v('org_id'),[''=>'Yo‘q']+$orgLabels,['options'=>$orgOptions]) ?></div><?= Ui::input('HEMIS ID (mavjud hisobni import bilan bog‘lash)','hemis_id',$v('hemis_id'),'text',['maxlength'=>40,'pattern'=>'[0-9]{1,40}','placeholder'=>'Yo‘q']) ?><?= Ui::input('Ilmiy daraja','degree',$v('degree')) ?><?= Ui::input('Lavozim','position',$v('position')) ?><?php foreach(['academic_rank'=>'Ilmiy unvon','employment_form'=>'Ish turi','employment_staff'=>'Stavka','employee_type'=>'Xodim turi','phone'=>'Telefon','email'=>'Email'] as $key=>$label): ?><?= Ui::input($label,'profile['.$key.']',Yii::$app->request->post('profile',[])[$key]??$profile[$key]??'','text',['maxlength'=>200,'placeholder'=>'Yo‘q']) ?><?php endforeach ?><?= Ui::input($edit?'Yangi vaqtinchalik parol (ixtiyoriy)':'Vaqtinchalik parol','password','','password',['minlength'=>12,'maxlength'=>128,'autocomplete'=>'new-password','required'=>!$edit]) ?></div><label class="check"><?= Html::checkbox('active',(bool)$v('active',1)) ?> Faol hisob</label><div class="alert info">Yangi yoki tiklangan parol birinchi kirishda o‘zgartiriladi. Parolni foydalanuvchiga xavfsiz kanal orqali yetkazing.</div><div class="form-actions"><button class="button">Saqlash</button><?php if($edit)echo Html::a('Yangi hisob',['admin/users'],['class'=>'button secondary']); ?></div><?= Html::endForm() ?></section><aside class="card form-note"><h2>Vakolatlar</h2><p>O‘qituvchi o‘z arizalari bilan ishlaydi. Kafedra mudiri o‘z kafedrasini, fakultet mas’uli o‘z fakultetini ko‘radi.</p><p>Ekspert va rahbariyat umumiy natijalarni ko‘radi. Qaror faqat marshrutdagi tegishli rol tomonidan beriladi.</p><p>Hisobni faolsizlantirish oldingi natijalarni o‘chirmaydi.</p></aside></div><?php endif ?><section class="card"><h2>Hisoblar ro‘yxati</h2><div class="table-wrap"><table><thead><tr><th>Xodim</th><th>Login</th><th>Rol</th><th>Toifa</th><th>Biriktirilgan tuzilma / HEMIS profili</th><th>Holat</th><th></th></tr></thead><tbody><?php foreach($rows as $u): ?><tr><td><?= $this->render('_employee_photo',['person'=>$u]) ?><br><?= Ui::h($u->name) ?></td><td><?= Ui::h($u->username) ?></td><td><?= Ui::h(User::ROLES[$u->role]) ?></td><td><?= Ui::h(Catalog::CATEGORIES[$u->category]??'Yo‘q') ?></td><td><?= Ui::h($orgLabels[$u->org_id]??'Yo‘q') ?><details><summary>HEMIS profili</summary><?= $this->render('_employee_profile',['person'=>$u,'organizations'=>$orgs]) ?></details></td><td><?= $u->active?'Faol':'Nofaol' ?></td><td><?= Html::a('Tahrirlash',['admin/users','id'=>$u->id],['class'=>'text-link']) ?><?php if($super && (int)$u->id!==(int)Yii::$app->user->id): ?><?= Html::beginForm(['admin/delete-user','id'=>$u->id],'post') ?><button class="button small danger" type="submit">O‘chirish</button><?= Html::endForm() ?><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
